<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order <?= $e($order['order_number']) ?></title>
<style>:root{--ink:#292d29;--muted:#706e65;--line:#e5e0d6;--teal:#647158}body{font:15px/1.6 Inter,system-ui,sans-serif;color:var(--ink);max-width:1100px;margin:2rem auto;padding:1rem}h1{font-size:22px;margin-bottom:4px}h2{font-size:15px;margin:0}h3{font-size:12px;color:var(--teal);letter-spacing:.08em;text-transform:uppercase;margin:28px 0 6px}table{width:100%;border-collapse:collapse;font-size:.85rem;margin-top:4px}th{text-align:left;color:var(--muted);font-weight:600;border-bottom:2px solid var(--line)}td,th{padding:.55rem .5rem}td{border-bottom:1px solid var(--line)}dl{max-width:24rem;margin-left:auto;display:grid;grid-template-columns:1fr auto;gap:6px 24px}dd{text-align:right;margin:0}dl dt:last-of-type,dl dd:last-of-type{font-weight:700;border-top:1px solid var(--line);padding-top:8px}address{font-style:normal;color:var(--muted)}.lines{overflow:auto}.actions{display:flex;gap:12px;margin-bottom:24px}.actions button,.actions a{display:inline-block;padding:10px 16px;border-radius:6px;font:inherit;cursor:pointer;text-decoration:none;border:1px solid var(--line)}.actions button{background:var(--teal);color:#fff;border-color:var(--teal)}.actions a{background:#fff;color:var(--ink)}@media print{.actions{display:none}body{margin:0;padding:0;font-size:11pt;color:#000}table{font-size:9pt}tr{break-inside:avoid}.lines{overflow:visible}@page{margin:15mm}}</style></head><body>
