<h1>Maa Sarada · Order summary</h1><h2><?= $e($order['order_number']) ?></h2><p>Placed <?= $e(gmdate('d M Y H:i',(int)$order['created_at'])) ?> UTC</p>
<h3>Delivery address</h3><address><?php foreach(['recipient','line1','line2','city','state','postal_code','country_code','phone'] as $field): ?><?php if(($order['address'][$field]??'')!==''): ?><?= $e($order['address'][$field]) ?><br><?php endif; ?><?php endforeach; ?></address>
